from collections import deque
from typing import Mapping, Sequence, Tuple, List

def shortest_path(graph: Mapping[int, Sequence[int]], source: int, target: int) -> Tuple[int, List[int]]:
    queue = deque([source])
    parent: dict[int, int | None] = {source: None}
    while queue:
        vertex = queue.popleft()
        if vertex == target:
            break
        for neighbor in graph[vertex]:
            if neighbor not in parent:
                parent[neighbor] = vertex
                queue.append(neighbor)
    if target not in parent:
        raise ValueError("target is unreachable")
    path: List[int] = []
    cursor: int | None = target
    while cursor is not None:
        path.append(cursor)
        cursor = parent[cursor]
    path.reverse()
    return len(path) - 1, path

if __name__ == "__main__":
    graph = {0: [1], 1: [0, 2], 2: [1, 3], 3: [2]}
    print(shortest_path(graph, 0, 3))

from dataclasses import dataclass

@dataclass(frozen=True)
class Diagnostic:
    n: int
    k: int
    d: int
    graph_distance: int

    def report(self) -> dict[str, int | bool]:
        code_margin = self.n + 2 - (2 * self.d + self.k)
        geometric_margin = self.n + 2 - (2 * self.graph_distance + self.k)
        return {"exact_realization": self.d == self.graph_distance,
                "code_margin": code_margin,
                "geometric_margin": geometric_margin,
                "saturated": code_margin == 0 and geometric_margin == 0}

if __name__ == "__main__":
    print(Diagnostic(5, 1, 3, 3).report())

