from typing import Iterable, List, Tuple

def defect_table(rate_percent: int, sizes: Iterable[int]) -> List[Tuple[int, int, int]]:
    rows: List[Tuple[int, int, int]] = []
    for n in sizes:
        k = rate_percent * n // 100
        rows.append((n, k, max(0, k - 2)))
    return rows

if __name__ == "__main__":
    for row in defect_table(20, [20, 50, 100, 200]):
        print(row)

